var SelectedDragable=0,CurrVarName='',
GlobalSelection =null,
CurrDragIsUnEndlich='',
CurrKartZuShau='',
CurrKartMitKarte='',
CurrKarte='',
CurrVarName='',
CurrFeildWidth='',
CurrFeildHeight='',
CurrKartValue='';
tinymce.PluginManager.add('ifbq_dragables', function(editor, url) {
	
	editor.addButton('dragables', {
		text: 'Ablage',
		icon: 'table',
		image: tinymce.baseURL + '/plugins/ifbq_dragables/drag.png',
		id: 'dragable_antwortElement',
		class: 'dragables',
		tooltip:'Antwortelement',
		stateSelector:"img .dragables",
		onclick: function() {
			      // Open window
			editor.windowManager.open({
				width: 500,
				height: 350,
				title: 'Variable Name ausfüllen',
				body: [
					{
						type: 'container',
						height: 300,
						forced_root_block : "",
						name: '',
						label: '',
						html:'Variable: <input style="border: 1px solid gray;margin-bottom: 8px;" id="drag_var" name="drag_var" value="'+CurrVarName+'">'+
						'<p>Breite: <input style="border: 1px solid gray;margin-bottom: 8px;" type="Text" name="dWidth" id="dWidth" value="'+CurrFeildWidth+'"></p>'+
						'<p>Höhe: <input style="border: 1px solid gray;margin-bottom: 8px;" type="Text" name="dHeight" id="dHeight" value="'+CurrFeildHeight+'"></p>'+
						'<p>Unendlich nutzbar: <input type="checkbox" name="unendlich" id="unendlich" '+CurrDragIsUnEndlich+'></p>'+
						'<p>Mit Karte: <input type="checkbox" name="mitkart" id="mitkart" '+CurrKartMitKarte+'></p>'+
						'<div style="height:280px;">'+
						'	<div id="dwert" style="display:none;height:280px;'+CurrKartZuShau+'">'+
						'		<p>Kartewert: <input style="border: 1px solid gray;margin-bottom: 8px;" type="text" name="karteval" id="karteval" value="'+CurrKartValue+'"></p>'+
						'		<textarea id="werteditor"></textarea>'+
						'	</div>'+
						'</div>'
					}
				],
				onSubmit: function(api) {					
					var dWidth = $('#dWidth').val();
					var dHeight = $('#dHeight').val();
					if(!dWidth || !dHeight || parseInt(dWidth) <10 || parseInt(dHeight) <10){
						alert('Die Höhe und Breite sollen größer als 10!!');
						return false;
					}
					var dVarname = $('#drag_var').val();
					var dVarStatus = $('#unendlich').is(":checked");
					var dVarMit = $('#mitkart').is(":checked");
					var dKarteval = $('#karteval').val();
					var dContent = tinymce.get("werteditor").getContent();
					var dVarKart = (dVarMit)?  '<span class="antwort-element ablagestart" data-value="'+dKarteval+'" >'+dContent +'</span>' : '';
					//var BGImage =(dVarMit)? '': 'background-image:url(../bundles/concertopanel/files/dragpos2.png);';					
					dObject ='<span id="dragable_'+dVarname+'" data-option="'+dVarStatus+'" data-var="'+dVarname+'"  contentEditable="false" style="width:'+dWidth+'px !important;height:'+dHeight+'px !important;" class="ablageziel mceNonEditable dragable" data-wert="'+dVarMit+'">'+dVarKart+'</span>';
					if(GlobalSelection)
						GlobalSelection.outerHTML = dObject;
					else
						editor.selection.setContent(dObject);

					GlobalSelection =null;
					CurrDragIsUnEndlich='';
					CurrKartZuShau='';
					CurrKartMitKarte='';
					CurrKarte='';
					CurrVarName='';
					CurrFeildWidth='';
					CurrFeildHeight='';
					CurrKartValue='';
					
					SelectedDragable++;
					tinymce.remove('textarea#werteditor');
				  },
				onCancel: function() {					
					tinymce.remove('textarea#werteditor');
					GlobalSelection =null;
					CurrDragIsUnEndlich='';
					CurrKartZuShau='';
					CurrKartMitKarte='';
					CurrKarte='';
					CurrVarName='';
					CurrFeildWidth='';
					CurrFeildHeight='';
					CurrKartValue='';
				  },
				onClose: function() {					
					tinymce.remove('textarea#werteditor');
					GlobalSelection =null;
					CurrDragIsUnEndlich='';
					CurrKartZuShau='';
					CurrKartMitKarte='';
					CurrKarte='';
					CurrVarName='';
					CurrFeildWidth='';
					CurrFeildHeight='';
					CurrKartValue='';
				  }
			});
			
			tinymce.init({
				selector: 'textarea#werteditor',
				menubar: false,
				language: 'de',
				readonly: 0,
				forced_root_block : "",
				  plugins: [
					'image','code','autoresize'
				  ],
				toolbar: 'styleselect | bold italic | alignleft aligncenter alignright alignjustify | bullist numlist outdent indent | image | code',
				setup: function(editor) {
					editor.on('init', function() {
						klineeditorexists=true;
						if(CurrKarte){
							editor.setContent(CurrKarte);
						}							
					});
				},
			});

			$('#mitkart').click(function(e) {
				if(this.checked)
					$('#dwert').show();
				else
					$('#dwert').hide();
			});

			$('.dragable').click(function(e) {
				SelectedDragable=$(this).attr('data-value');
			});
		}
	});
});
